static func create(id: UUID = UUID()) throws -> OathWalletSecret {
    guard let wallet = HDWallet(strength: 128, passphrase: "") else {
        throw OathWalletError.unavailable
    }
    return OathWalletSecret(id: id, mnemonic: wallet.mnemonic, language: "english",
                            createdAt: .now, backedUp: false)
}

func seal(_ data: Data, context: String) throws -> Data {
    try lock.withLock {
        let record = try loadKey()
        let sealed = try AES.GCM.seal(data, using: SymmetricKey(data: record.key),
                                      authenticating: authenticationData(record.id, context: context))
        guard let combined = sealed.combined else { throw OathInstallationSecurityError.invalidRecord }
        return try JSONEncoder().encode(SealedRecord(version: 1, installationID: record.id, sealed: combined))
    }
}

static func signEVM(_ plan: EVMSendPlan, secret: OathWalletSecret, account: AccountRecord) throws -> EVMSignedSend {
    try Task.checkCancellation()
    guard account.walletID == secret.id.uuidString, account.networkID == plan.network.rawValue,
          let chain=OathImportChain(rawValue:account.networkID),chain.isEVM,
          try EVMSendIdentity.address(account.address) == plan.sender else { throw EVMSendError.wrongOwner }
    if let material = secret.evmMultisig {
        guard material.network == account.networkID, account.derivationPath == "evm-multisig-v1",
              let context = plan.multisig, try context.policy == material.policy() else { throw EVMSendError.wrongOwner }
        var keys = try material.signers.map { try $0.signingKey() }
        defer { for i in keys.indices { keys[i].resetBytes(in: 0..<keys[i].count) } }
        return try EVMMultisigCrypto.sign(plan, keys: keys, executorKey: material.executorKey)
    }

public static func open(_ data: Data, password: String) throws -> BackupWallet {
    try validate(password: password)
    guard data.count <= maximumBytes else { throw CloudBackupError.invalidDocument }
    let envelope: Envelope
    do { envelope = try JSONDecoder().decode(Envelope.self, from: data) }
    catch { OathDiagnostics.record(error); throw CloudBackupError.invalidDocument }
    let h = envelope.header
    guard h.format == "org.oathwallet.encrypted-wallet", (1...21).contains(h.version),
          h.cipher == "AES-256-GCM", h.kdf == "PBKDF2-HMAC-SHA256",
          h.passwordNormalization == "NFC",
          h.rounds == iterations, h.salt.count == 32, envelope.sealed.count >= 28 else {
        throw CloudBackupError.invalidDocument
    }
    let key = try derive(password, salt: h.salt)
    var plaintext: Data
    do {
        plaintext = try AES.GCM.open(AES.GCM.SealedBox(combined: envelope.sealed),
                                     using: key, authenticating: encoder().encode(h))
    } catch { OathDiagnostics.record(error); throw CloudBackupError.authenticationFailed }
